gcc='gcc:15@sha256:eb5e64286ad47187b32bda75c6b6916166ecb41da56559b8b09e0001748d2cce';cmd=[*common,'--entrypoint','objdump','-v',str(out)+':/bank:ro',gcc,'-d','-C','--no-show-raw-insn','/bank/solution'];q=subprocess.run(cmd,capture_output=True,text=True,timeout=120);assert q.returncode==0 and not q.stderr;asm=out/'disassembly.txt';asm.write_text(q.stdout);pattern=r'^([0-9a-f]+ <Names::first\([^\n]+\)>:)\n(.*?)(?=\n[0-9a-f]+ <|\Z)';match=re.search(pattern,q.stdout,re.M|re.S);assert match,'Keep report honest if compiler inlines function';clip=match.group(0);(out/'names-first.txt').write_text(clip)
